54	    @Override
55	    public List<MaterialNotifyTaskAutomation> queryLatestNotifyUnDoneByDimension(MaterialNotifyTaskAutomationQueryCondition condition) {
56	        if (condition == null || CollectionUtils.isEmpty(condition.getDimensions())) {
57	            return Collections.emptyList();
58	        }
59	        logger.info("queryLatestNotifyUnDoneByDimension condition={}", condition);
60	        List<MaterialNotifyTaskAutomationQueryCondition.Dimension> dimensions = condition.getDimensions();
61	        if (dimensions.size() <= MAX_DIMENSIONS_PER_QUERY) {
62	            return materialNotifyTaskAutomationMapper.queryLatestNotifyUnDoneByDimension(condition);
63	        }
64	        // 维度过多：按批查询后合并，避免单条 SQL 的 (project_order_id, material_code) IN 列表过大
65	        List<MaterialNotifyTaskAutomation> result = new ArrayList<>();
66	        for (List<MaterialNotifyTaskAutomationQueryCondition.Dimension> partition : Lists.partition(dimensions, MAX_DIMENSIONS_PER_QUERY)) {
67	            MaterialNotifyTaskAutomationQueryCondition chunkCondition = MaterialNotifyTaskAutomationQueryCondition.builder()
68	                    .dimensions(partition)
69	                    .taskType(condition.getTaskType())
70	                    .notifyExecuteType(condition.getNotifyExecuteType())
71	                    .build();
72	            List<MaterialNotifyTaskAutomation> records = materialNotifyTaskAutomationMapper
73	                    .queryLatestNotifyUnDoneByDimension(chunkCondition);
74	            logger.info("queryLatestNotifyUnDoneByDimension chunkCondition={} 查询结果={}", chunkCondition, records);
75	            if (!CollectionUtils.isEmpty(records)) {
76	                result.addAll(records);
77	            }
78	        }
79	        return result;
80	    }
