132	    @Override
133	    public NotifyTaskJudgeStatusVO queryNotifyTaskJudgeStatus(NotifyTaskJudgeStatusItemParam param) {
134	        if (param == null || param.getTaskDispatchId() == null) {
135	            throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL,
136	                    "taskDispatchId不能为空");
137	        }
138	
139	        // 按任务id查询待通知复尺节点，项目/品类/任务类型以查询结果为准。
140	        TaskDispatchParam taskDispatchParam = TaskDispatchParam.builder()
141	                .taskDispatchIds(Collections.singletonList(param.getTaskDispatchId()))
142	                .nodeType(NOTIFY_NODE_TYPE)
143	                .taskType(DEFAULT_TASK_TYPE)
144	                .processStatus(ProcessStatusEnum.UNFINISHED.getValue())
145	                .build();
146	        List<TaskDispatchDTO> taskList = taskDispatchNodeDao.listTaskByCondition(taskDispatchParam);
147	        if (CollectionUtils.isEmpty(taskList)) {
148	            throw new UtopiaBussinessException(ResultCodeEnum.ERROR_NO_DATA, "未查到待通知复尺节点");
149	        }
150	        TaskDispatchDTO task = taskList.get(0);
151	
152	        // 开城品类code列表：自动通知开关配置的品类全集（即 categoryMatched 的判定全集）。
153	        Map<String, NotifyAutomationConfig.DimensionRule> autoNotifyRules = notifyAutomationConfig.parseAutoNotifyRules();
154	        NotifyTaskJudgeStatusVO result = NotifyTaskJudgeStatusVO.builder()
155	                .taskDispatchNodeId(task.getTaskDispatchNodeId())
156	                .materialCodes(new ArrayList<>(autoNotifyRules.keySet()))
157	                .judgeResult(NOT_JUDGED)
158	                .recognized(NOT_RECOGNIZED)
159	                .categoryMatched(false)
160	                .build();
161	        // 先过品类校验：未命中通知复尺配置的品类不查识别表，recognized/judgeResult 保持 0（未判定）。
162	        // 与执行记录的品类口径一致，仅判断配置中是否存在该品类。
163	        boolean categoryMatched = autoNotifyRules.containsKey(task.getMaterialCode());
164	        result.setCategoryMatched(categoryMatched);
165	        if (!categoryMatched) {
166	            return result;
167	        }
168	
169	        // 识别表无节点id，按项目/品类/任务类型精确维度查询，避免不同任务类型串数据。
170	        // 不传notifyExecuteType，不限制判定结果、执行状态和识别日期；取识别结果表最新一条的判定值。
171	        Map<String, MaterialNotifyTaskAutomation> recognition =
172	                queryLatestNotifyUnDoneByDimension(Collections.singletonList(task), task.getTaskType());
173	        MaterialNotifyTaskAutomation recognizeResult =
174	                recognition.get(dimensionKey(task.getProjectOrderId(), task.getMaterialCode()));
175	        if (recognizeResult == null) {
176	            return result;
177	        }
178	        // 有识别记录即已判定：recognized=1；判定值原样透出，表里为空按 5（无结果）兜底。
179	        result.setRecognized(RECOGNIZED);
180	        result.setJudgeResult(recognizeResult.getJudgeResult() == null
181	                ? NotifyJudgeResultEnum.NONE_RESULT.getValue()
182	                : recognizeResult.getJudgeResult().intValue());
183	        return result;
184	    }
