227	    /**
228	     * 通知复尺查询公共方案：查 node → 重启去重 → automation 判定 → 归组（可通知/延期预警）→ 延期≤3天过滤。
229	     * 不含排序、地址、项目分组（各调用方按需处理）；judge=4（现场已完成，纯提醒，仅push）不进入结果。
230	     *
231	     * @param executorId 工长 ucid
232	     * @param param      查询参数，可空（空视为默认 taskType=3、无 projectOrderId 过滤）
233	     */
234	    private NotifyTaskSplitResult queryNotifyTaskSplit(String executorId, NotifyTaskQueryParam param) {
235	        if (StringUtils.isEmpty(executorId)) {
236	            throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, "工长不能为空");
237	        }
238	        Integer taskType = param == null || param.getTaskType() == null ? DEFAULT_TASK_TYPE : param.getTaskType();
239	        logger.info("queryNotifyTaskSplit executorId={}, taskType={}, param={}", executorId, taskType, param);
240	        // 获取主材任务
241	        TaskDispatchParam taskDispatchParam = new TaskDispatchParam();
242	        taskDispatchParam.setExecutorId(executorId);
243	        taskDispatchParam.setTaskType(taskType);
244	        taskDispatchParam.setNodeType(NOTIFY_NODE_TYPE);
245	        taskDispatchParam.setProcessStatus(ProcessStatusEnum.UNFINISHED.getValue());
246	        if (param != null && param.getProjectOrderId() != null) {
247	            taskDispatchParam.setProjectOrderId(param.getProjectOrderId());
248	        }
249	        List<TaskDispatchDTO> taskList = taskDispatchNodeDao.listTaskByCondition(taskDispatchParam);
250	        if (CollectionUtils.isEmpty(taskList)) {
251	            return new NotifyTaskSplitResult(new ArrayList<>(), new ArrayList<>(), Collections.emptyMap());
252	        }
253	
254	        // 获取订单信息
255	        Set<Long> projectOrderIds = new HashSet<>();
256	        taskList.forEach(task -> projectOrderIds.add(task.getProjectOrderId()));
257	        Map<Long, ProjectOrderDetailBO> projectOrderMap = fetchProjectOrders(projectOrderIds);
258	
259	        long start = System.currentTimeMillis();
260	        // 获取推荐结果：按 (project_order_id, material_code, task_type)
261	        Map<String, MaterialNotifyTaskAutomation> notifyTaskAutomationMap = queryLatestNotifyUnDoneByDimension(taskList,
262	                taskType);
263	        long end = System.currentTimeMillis();
264	        log.info("queryLatestNotifyUnDoneByDimension cost: {}", end - start);
265	        List<NotifyTaskDetailVO> notifyTasks = new ArrayList<>();
266	        List<NotifyTaskDetailVO> delayTasks = new ArrayList<>();
267	        for (TaskDispatchDTO task : taskList) {
268	            // 校验开关
269	            ProjectOrderDetailBO order = projectOrderMap.get(task.getProjectOrderId());
270	            String gbCode = order == null ? null : order.getGbCode();
271	            String departmentCode = resolveDepartmentCode(order);
272	            if (!notifyAutomationConfig.isFeatureOpen(gbCode, executorId, departmentCode)) {
273	                logger.info("feature is not open for task: {}, gbCode: {}, executorId: {}, departmentCode: {}", task, gbCode, executorId, departmentCode);
274	                continue;
275	            }
276	            MaterialNotifyTaskAutomation materialNotifyTaskAutomation = notifyTaskAutomationMap
277	                    .get(dimensionKey(task.getProjectOrderId(), task.getMaterialCode()));
278	            Integer judgeResult = materialNotifyTaskAutomation == null || materialNotifyTaskAutomation.getJudgeResult() == null
279	                    ? NotifyJudgeResultEnum.CANNOT_JUDGE.getValue()
280	                    : materialNotifyTaskAutomation.getJudgeResult().intValue();
281	            logger.info("task={}, judgeResult={}", task, judgeResult);
282	            // judge=1 可通知；judge=2/3/4无automation记录 归延期预警；
283	            if (NotifyJudgeResultEnum.CAN_NOTIFY.getValue().equals(judgeResult)) {
284	                NotifyTaskDetailVO vo = buildDetail(task, materialNotifyTaskAutomation, projectOrderMap);
285	                notifyTasks.add(vo);
286	            } else {
287	                LocalDate cutoffDate = LocalDate.now().plusDays(DELAY_FILTER_WINDOW_DAYS);
288	                if (task.getEstimatedTime() != null && !task.getEstimatedTime().toInstant()
289	                        .atZone(ZoneId.systemDefault())
290	                        .toLocalDate()
291	                        .isAfter(cutoffDate)) {
292	                    NotifyTaskDetailVO vo = buildDetail(task, null, projectOrderMap);
293	                    if (materialNotifyTaskAutomation != null
294	                            && materialNotifyTaskAutomation.getJudgeResult().equals(NotifyJudgeResultEnum.CANNOT_NOTIFY.getValue().byteValue())) {
295	                        vo.setJudgeReason(materialNotifyTaskAutomation.getJudgeRemark());
296	                        vo.setJudgeResult(NotifyJudgeResultEnum.CANNOT_NOTIFY.getValue());
297	                        vo.setImages(splitImages(materialNotifyTaskAutomation.getImages()));
298	                    }
299	                    delayTasks.add(vo);
300	                }
301	            }
302	        }
303	        return new NotifyTaskSplitResult(notifyTasks, delayTasks, projectOrderMap);
304	    }
