306	    private boolean isInNotifyWindow() {
307	        if (apolloConfig.getMaterialNotifyTimeWindowEnabled()) {
308	            return true;
309	        }
310	        LocalTime now = LocalTime.now();
311	        for (String window : NOTIFY_WINDOWS) {
312	            String[] range = window.split("-");
313	            LocalTime start = LocalTime.parse(range[0]);
314	            LocalTime end = LocalTime.parse(range[1]);
315	            if (!now.isBefore(start) && !now.isAfter(end)) {   // 含端点
316	                return true;
317	            }
318	        }
319	        return false;
320	    }
321	
322	    /**
323	     * 分批(10/批) + 并行拉取工地订单详情，单批超时 3s，超时/失败仅跳过该批（对应工地无地址，不影响其余）。
324	     */
325	    private Map<Long, ProjectOrderDetailBO> fetchProjectOrders(Set<Long> projectOrderIds) {
326	        Map<Long, ProjectOrderDetailBO> projectOrderMap = new LinkedHashMap<>();
327	        if (CollectionUtils.isEmpty(projectOrderIds)) {
328	            return projectOrderMap;
329	        }
330	        for (List<Long> partition : Lists.partition(Lists.newArrayList(projectOrderIds), 50)) {
