477	    @Override
478	    public NotifyTaskBatchHandleResultVO batchHandleNotifyTasks(NotifyBatchHandleParam param) {
479	        if (CollectionUtils.isEmpty(param.getTaskDispatchNodeItems())) {
480	            return NotifyTaskBatchHandleResultVO.builder().successCount(0).successList(Collections.emptyList()).failList(Collections.emptyList()).build();
481	        }
482	        logger.info("batchHandleNotifyTasks param: {}", param);
483	        Map<Long, NotifyNodeHandleItem> itemMap = param.getTaskDispatchNodeItems().stream()
484	                .collect(Collectors.toMap(NotifyNodeHandleItem::getTaskDispatchNodeId, Function.identity(), (o1, o2) -> o1));
485	        List<Long> nodeIdList = param.getTaskDispatchNodeItems().stream()
486	                .map(NotifyNodeHandleItem::getTaskDispatchNodeId)
487	                .collect(Collectors.toList());
488	
489	        // 节点
490	        List<TaskDispatchNode> nodes = taskDispatchNodeDao.listByIds(nodeIdList);
491	        Map<Long, TaskDispatchNode> nodeMap = nodes.stream()
492	                .collect(Collectors.toMap(TaskDispatchNode::getId, Function.identity(), (o1, o2) -> o1));
493	        Set<Long> dispatchIds = nodes.stream()
494	                .map(TaskDispatchNode::getTaskDispatchId)
495	                .collect(Collectors.toSet());
496	        // task
497	        List<TaskDispatch> taskDispatches = taskDispatchDao.listByIds(Lists.newArrayList(dispatchIds));
498	        Map<Long, TaskDispatch> dispatchMap = taskDispatches.stream()
499	                .collect(Collectors.toMap(TaskDispatch::getId, Function.identity(), (o1, o2) -> o1));
500	
501	        // 获取推荐
502	        Map<String, MaterialNotifyTaskAutomation> autoMap = queryLatestNotifyUnDoneByDimension2(taskDispatches, DEFAULT_TASK_TYPE);
503	
504	        List<Long> successNodeIds = new ArrayList<>();
505	        List<Long> failedNodeIds = new ArrayList<>();
506	        // 操作员
507	        IOperator operator = OperatorContextHandler.getContext().getOperator();
508	        OperatorDTO operatorDTO = new OperatorDTO();
509	        operatorDTO.setUcid(String.valueOf(operator.getUcid()));
510	        operatorDTO.setUsername(operator.getUsername() + "（一键通知复尺）");
511	
512	        for (TaskDispatchNode node : nodes) {
513	            if (node.getTaskDispatchId() != null
514	                    && ProcessStatusEnum.FINISHED.getValue().equals(node.getProcessStatus().intValue())) {
515	                log.info("batchHandleNotifyTasks skip completed node: {}", node.getId());
516	                continue;
517	            }
518	            try {
519	                MaterialNotifyTaskAutomation auto = autoMap.get(dimensionKey(
520	                        node.getProjectOrderId(),
521	                        dispatchMap.get(node.getTaskDispatchId()).getMaterialCode()));
522	                DispatchHandleParam handleParam = new DispatchHandleParam();
523	                handleParam.setTaskDispatchNodeId(node.getId());
524	                // 图片必须大于等于3张
525	                if (itemMap.get(node.getId()).getImages().size() < 3) {
526	                    logger.warn("batchHandleNotifyTasks skip node {} due to images size < 3", node.getId());
527	                    failedNodeIds.add(node.getId());
528	                    continue;
529	                }
530	                // 设置图片和上门时间
531	                handleParam.setImages(itemMap.get(node.getId()).getImages());
532	                handleParam.setQualified(itemMap.get(node.getId()).getQualified());
533	                handleParam.setRemarks(itemMap.get(node.getId()).getRemarks());
534	                handleParam.setNoticeRetainTime(itemMap.get(node.getId()).getNoticeRetainTime());
535	                materialHandleV2Service.handleNode(handleParam, operatorDTO);
536	
537	                Integer adoptionType = classifyAdoption(auto, new HashSet<>(handleParam.getImages()), handleParam.getNoticeRetainTime());
538	                // 一键通知挂载：handleNode 已成功，执行方式=一键(1)；采纳快照由 doRecord 内部比对识别表与节点提交值算出
539	                notifyExecuteRecordService.recordAfterHandle(node.getId(), handleParam.getQualified(),
540	                        NotifyExecuteTypeEnum.ONE_KEY_NOTIFY.getValue().intValue());
541	                MaterialNotifyTaskAutomation update = MaterialNotifyTaskAutomation.builder()
542	                        .id(auto.getId())
543	                        .notifyExecuteType(NotifyExecuteTypeEnum.ONE_KEY_NOTIFY.getValue())
544	                        .aiAdoptionType(adoptionType == null ? 0 : adoptionType.byteValue())
545	                        .build();
546	
547	                materialNotifyTaskAutomationDao.updateById(update);
548	                successNodeIds.add(node.getId());
549	            } catch (Exception e) {
550	                failedNodeIds.add(node.getId());
551	                log.error("batchHandleNotifyTasks error: {}", node.getId(), e);
552	            }
553	        }
554	        // 所有节点 ID 列表以及项目 ID 集合
555	        List<Long> allNodeIds = new ArrayList<>(
556	                successNodeIds.size() + failedNodeIds.size());
557	
558	        allNodeIds.addAll(successNodeIds);
559	        allNodeIds.addAll(failedNodeIds);
560	
561	        Set<Long> projectOrderIds = allNodeIds.stream()
562	                .map(nodeMap::get)
563	                .filter(Objects::nonNull)
564	                .map(TaskDispatchNode::getProjectOrderId)
565	                .filter(Objects::nonNull)
566	                .collect(Collectors.toSet());
567	        // 项目订单信息
568	        Map<Long, ProjectOrderDetailBO> projectOrderMap =
569	                fetchProjectOrders(projectOrderIds);
570	        // 构建任务详情,按照项目汇总
571	        List<NotifyTaskDetailVO> successTasks = buildTaskDetails(successNodeIds, nodeMap, dispatchMap);
572	        List<NotifyTaskDetailVO> failedTasks = buildTaskDetails(failedNodeIds, nodeMap, dispatchMap);
573	        List<NotifyTaskProjectGroupVO> failedProjects = groupByProject(failedTasks, projectOrderMap);
574	        List<NotifyTaskProjectGroupVO> successProjects = groupByProject(successTasks, projectOrderMap);
575	
576	        return NotifyTaskBatchHandleResultVO.builder()
577	                .successCount(successNodeIds.size())
578	                .successList(successProjects)
579	                .failList(failedProjects)
580	                .build();
581	    }
