609	    public NotifyTaskAutoFillVO queryNotifyTaskAutoFill(NotifyTaskAutoFillParam param) {
610	        IOperator operator = OperatorContextHandler.getContext().getOperator();
611	        String executorId = String.valueOf(operator.getUcid());
612	        logger.info("queryNotifyTaskAutoFill param: {}", param);
613	        // 1. node 必须存在
614	        TaskDispatchNode node = taskDispatchNodeDao.getById(param.getTaskDispatchNodeId());
615	        if (node == null) {
616	            throw new UtopiaBussinessException(ResultCodeEnum.ERROR_PARAM_ILLEGAL, MessageConstant.TASK_NONE_EXIST);
617	        }
618	        Long projectOrderId = node.getProjectOrderId();
619	
620	        // 2. Apollo 开关 gate（与 filterByFeatureSwitch 同口径：gbCode/工程部取 ProjectOrderDetailBO）
621	        ProjectOrderDetailBO order = fetchProjectOrders(Collections.singleton(projectOrderId)).get(projectOrderId);
622	        String gbCode = order == null ? null : order.getGbCode();
623	        String departmentCode = resolveDepartmentCode(order);
624	        if (!notifyAutomationConfig.isFeatureOpen(gbCode, executorId, departmentCode)) {
625	            return NotifyTaskAutoFillVO.builder()
626	                    .taskDispatchNodeId(node.getId())
627	                    .projectOrderId(String.valueOf(projectOrderId))
628	                    .taskType(null)
629	                    .images(Collections.emptyList())
630	                    .recommendVisitTime(null)
631	                    .build();
632	        }
633	
634	        // 3. 取 dispatch 拿 taskType + materialCode（taskType 为返回字段必查）
635	        TaskDispatch dispatch = taskDispatchDao.getById(node.getTaskDispatchId());
636	        Integer taskType = dispatch.getTaskType();
637	        String materialCode = dispatch.getMaterialCode();
638	        logger.info("queryNotifyTaskAutoFill nodeId: {}, taskType: {}, materialCode: {}", node.getId(), taskType, materialCode);
639	
640	        // 4. 先看 node 有没有：node 缺图片或缺上门时间才去查 automation（避免无谓查询）
641	        boolean nodeHasImages = !StringUtils.isEmpty(node.getImages());
642	        Calendar calendar = Calendar.getInstance();
643	        calendar.setTime(node.getNoticeRetainTime());
644	        boolean nodeHasTime = calendar.get(Calendar.YEAR) >= 2010;   // node 时间小于 2010 年视为无效
645	
646	        List<String> images;
647	        Date recommendVisitTime;
648	        if (nodeHasImages || nodeHasTime) {
649	            images = splitImages(node.getImages());
650	            recommendVisitTime = node.getNoticeRetainTime();
651	        } else {
652	            TaskDispatchDTO dto = new TaskDispatchDTO();
653	            dto.setProjectOrderId(projectOrderId);
654	            dto.setMaterialCode(materialCode);
655	            Map<String, MaterialNotifyTaskAutomation> autoMap =
656	                    queryLatestNotifyUnDoneByDimension(Collections.singletonList(dto), taskType);
657	            MaterialNotifyTaskAutomation auto = autoMap.get(dimensionKey(projectOrderId, materialCode));
658	            images = auto == null ? Collections.emptyList() : splitImages(auto.getImages());
659	            recommendVisitTime = auto == null ? null : auto.getRecommendVisitTime();
660	        }
661	        return NotifyTaskAutoFillVO.builder()
662	                .taskDispatchNodeId(node.getId())
663	                .projectOrderId(String.valueOf(projectOrderId))
664	                .taskType(taskType)
665	                .images(images)
666	                .recommendVisitTime(recommendVisitTime)
667	                .build();
668	    }
