705	    /**
706	     * 自动执行通知任务：扫描 automation 表「昨日识别 + 可通知(judge=1) + 未执行(notify_execute_type=0)」候选，
707	     * 维度反查待通知节点（taskType=3 / nodeType=20 / processStatus=2）后，逐件经 autoNotify 开关校验，
708	     * 复用 handleNode 全链路完成通知（images/时间取自 automation 行）。受 notification.remeasure.automation.autoNotify 管控。
709	     */
710	    @Override
711	    public NotifyTaskAutoExecuteResultVO autoExecuteNotifyTasks() {
712	        MaterialNotifyTaskAutomation condition = MaterialNotifyTaskAutomation.builder()
713	                .judgeResult(NotifyJudgeResultEnum.CAN_NOTIFY.getValue().byteValue())
714	                .taskType(DEFAULT_TASK_TYPE)
715	                .build();
716	        List<MaterialNotifyTaskAutomation> candidates = materialNotifyTaskAutomationDao.selectByEntity(condition);
717	        logger.info("autoExecuteNotifyTasks candidates count: {}", candidates.size());
718	        if (CollectionUtils.isEmpty(candidates)) {
719	            return NotifyTaskAutoExecuteResultVO.builder()
720	                    .candidateCount(0).executedCount(0).build();
721	        }
722	
723	        // 2. 维度反查待通知节点（taskType=3 / nodeType=20 / processStatus=2 / 无 executor 即系统级扫描）
724	        List<Long> projectOrderIdList = candidates.stream()
725	                .map(MaterialNotifyTaskAutomation::getProjectOrderId)
726	                .distinct().collect(Collectors.toList());
727	        List<String> materialCodeList = candidates.stream()
728	                .map(MaterialNotifyTaskAutomation::getMaterialCode)
729	                .filter(Objects::nonNull).distinct().collect(Collectors.toList());
730	        TaskDispatchParam nodeParam = new TaskDispatchParam();
731	        nodeParam.setProjectOrderIdList(projectOrderIdList);
732	        nodeParam.setMaterialCodeList(materialCodeList);
733	        nodeParam.setTaskTypeList(Collections.singletonList(DEFAULT_TASK_TYPE));
734	        nodeParam.setNodeTypeList(Collections.singletonList(NOTIFY_NODE_TYPE));
735	        nodeParam.setProcessStatus(ProcessStatusEnum.UNFINISHED.getValue());
736	        List<TaskDispatchDTO> nodeList = taskDispatchNodeDao.listTaskByCondition(nodeParam)
737	                .stream().filter(node -> RestartStatusEnum.FIRST.getValue().equals(node.getRestartCount()))
738	                .collect(Collectors.toList());
739	        logger.info("autoExecuteNotifyTasks nodeList count: {}", nodeList.size());
740	
741	        // listTaskByCondition 的 projectOrderIdList / materialCodeList 是独立 IN（AND 语义），
742	        // 会产生 projList × matList 的超集节点；按候选维度精确收敛，避免无关组合进入映射
743	        Map<String, MaterialNotifyTaskAutomation> candidateMap = candidates.stream()
744	                .collect(Collectors.toMap(c -> dimensionKey(c.getProjectOrderId(), c.getMaterialCode()),
745	                        c -> c, (existing, replacement) -> existing));
746	        nodeList = nodeList.stream()
747	                .filter(n -> candidateMap.containsKey(dimensionKey(n.getProjectOrderId(), n.getMaterialCode())))
748	                .collect(Collectors.toList());
749	        Map<String, TaskDispatchDTO> nodeMap = new LinkedHashMap<>();
750	        for (TaskDispatchDTO n : nodeList) {
751	            nodeMap.put(dimensionKey(n.getProjectOrderId(), n.getMaterialCode()), n);
752	        }
753	
754	
755	        OperatorDTO operatorDTO = new OperatorDTO();
756	        operatorDTO.setUsername("系统自动通知复尺");
757	
758	        List<NotifyTaskDetailVO> executedNodes = new ArrayList<>();
759	        Set<Long> nodeProjectIds = new HashSet<>();
760	        nodeList.forEach(n -> nodeProjectIds.add(n.getProjectOrderId()));
761	        Map<Long, ProjectOrderDetailBO> projectOrderMap = fetchProjectOrders(nodeProjectIds);
762	        Integer successCount = 0;
763	        for (TaskDispatchDTO node : nodeList) {
764	            ProjectOrderDetailBO order = projectOrderMap.get(node.getProjectOrderId());
765	            MaterialNotifyTaskAutomation materialNotifyTaskAutomation = candidateMap.get(dimensionKey(node.getProjectOrderId(), node.getMaterialCode()));
766	            if (splitImages(materialNotifyTaskAutomation.getImages()).size() < 3) {
767	                log.warn("autoExecuteNotifyTasks skip node {} due to invalid images", node);
768	                continue;
769	            }
770	            String gbCode = order == null ? null : order.getGbCode();
771	            String departmentCode = resolveDepartmentCode(order);
772	            if (!notifyAutomationConfig.isAutoNotifyOpen(
773	                    node.getMaterialCode(), gbCode, node.getExecutorId(), departmentCode)) {
774	                continue;
775	            }
776	            DispatchHandleParam handleParam = new DispatchHandleParam();
777	            handleParam.setTaskDispatchNodeId(node.getTaskDispatchNodeId());
778	            handleParam.setRemarks("自动通知复尺");
779	            handleParam.setImages(splitImages(materialNotifyTaskAutomation.getImages()));
780	            handleParam.setNoticeRetainTime(materialNotifyTaskAutomation.getRecommendVisitTime());
781	            try {
782	                materialHandleV2Service.handleNode(handleParam, operatorDTO);
783	                // 自动通知挂载：handleNode 已成功，执行方式=自动(2)；采纳快照由 doRecord 内部比对识别表与节点提交值算出（自动链路提交值即识别表推荐值，结果为采纳1）
784	                notifyExecuteRecordService.recordAfterHandle(node.getTaskDispatchNodeId(), handleParam.getQualified(),
785	                        NotifyExecuteTypeEnum.AUTO_NOTIFY.getValue().intValue());
786	
787	                MaterialNotifyTaskAutomation update = MaterialNotifyTaskAutomation.builder()
