176	    @PostMapping("/backdoor/resetNodeAndRecognize")
177	    public ResultDTO<String> resetNodeAndRecognize(@RequestBody List<Long> nodeIds, Integer taskType) {
178	        if (CollectionUtils.isEmpty(nodeIds)) {
179	            return new ResultDTO<String>().fail("nodeIds不能为空");
180	        }
181	
182	        List<TaskDispatchNode> nodes = taskDispatchNodeDao.listByIds(nodeIds);
183	        if (CollectionUtils.isEmpty(nodes)) {
184	            return new ResultDTO<String>().fail("node不存在");
185	        }
186	
187	        int nodeCount = 0;
188	        int recognizeCount = 0;
189	
190	        StringBuilder nodeIdStr = new StringBuilder();
191	
192	        for (TaskDispatchNode node : nodes) {
193	            if (Objects.equals(node.getProcessStatus(), (byte) 3)) {
194	                TaskDispatchNode update = new TaskDispatchNode();
195	                update.setId(node.getId());
196	                update.setProcessStatus((byte) 2);
197	                taskDispatchNodeDao.updateById(update);
198	                nodeCount++;
199	                nodeIdStr.append("taskDispatch:");
200	                nodeIdStr.append(node.getId()).append(",");
201	            }
202	
203	            TaskDispatch dispatch = taskDispatchDao.getById(node.getTaskDispatchId());
204	            if (dispatch == null) {
205	                continue;
206	            }
207	
208	            MaterialNotifyTaskAutomation query = new MaterialNotifyTaskAutomation();
209	            query.setProjectOrderId(node.getProjectOrderId());
210	            query.setMaterialCode(dispatch.getMaterialCode());
211	            query.setTaskType(taskType);
212	
213	            for (MaterialNotifyTaskAutomation record :
214	                    materialNotifyTaskAutomationDao.selectByEntity(query)) {
215	
216	                MaterialNotifyTaskAutomation update = new MaterialNotifyTaskAutomation();
217	                update.setId(record.getId());
218	                update.setNotifyExecuteType((byte) 0);
219	                update.setAiAdoptionType((byte) 0);
220	                materialNotifyTaskAutomationDao.updateById(update);
221	                nodeIdStr.append("materialNotifyTaskAutomation:");
222	                nodeIdStr.append(record.getId()).append(",");
223	                recognizeCount++;
224	            }
225	        }
226	
227	        return new ResultDTO<String>().success(
228	                String.format("节点重置%d个，识别结果重置%d条", nodeCount, recognizeCount, nodeIdStr));
229	    }
