321	    @PostMapping("/backdoor/sinvoke")
322	    @ResponseBody
323	    public ResultDTO sinvoke(String serviceName, String methodName,
324	            @RequestParam(value = "params", required = false) List<String> params)
325	            throws InvocationTargetException, IllegalAccessException {
326	        Object bean = ApplicationContextUtil.getApplicationContext().getBean(serviceName);
327	        Class<?> clazz = bean.getClass();
328	        Method[] methods = clazz.getMethods();
329	
330	        for (Method method : methods) {
331	            // 不支持重载方法
332	            if (method.getName().equals(methodName)) {
333	                if (params == null) {
334	                    Object result = method.invoke(bean);
335	                    return new ResultDTO<>().success(result);
336	                }
337	                Class<?>[] parameterTypes = method.getParameterTypes();
338	                Object[] paramObjects = new Object[params.size()];
339	                for (int index = 0; index < params.size(); index++) {
340	                    Object object = null;
341	
342	                    Class<?> type = parameterTypes[index];
343	                    if (type == Integer.class) {
344	                        object = new Integer(params.get(index));
345	                    } else if (type == String.class) {
346	                        if (params.get(index).equals("null")) {
347	                            object = null;
348	                        } else {
349	                            object = params.get(index);
350	                        }
351	                    } else if (type == Long.class) {
352	                        object = new Long(params.get(index));
353	                    } else if (type == Date.class) {
354	                        object = DateUtil.parse(params.get(index), "yyyy-MM-dd HH:mm:ss");
355	                    } else if (params.get(index).startsWith("{") || type == List.class) {
356	                        object = JsonUtils.readJsonToBean(params.get(index), parameterTypes[index]);
357	                    }
358	
359	                    // if(type == List.class){
360	                    // Type genericType = type.getGenericInterfaces();
361	                    // object = JsonUtils.readJsonToBean(params.get(index), new TypeReference<type>() {
362	                    // });
363	                    // }
364	                    paramObjects[index] = object;
365	                }
366	                Object result = method.invoke(bean, paramObjects);
367	                return new ResultDTO<>().success(result);
368	            }
369	        }
370	        return new ResultDTO<>().fail("没有这个方法");
371	    }
