950	    /**
951	     * 【测试】复尺提交调中控失败 → 给项目经理和设计师发 IM push（手动验证用后门）
952	     * <p>
953	     * {@code MaterialMeasureServiceImpl#pushResizeCommitFailMsg(Long, Throwable)} 是私有方法，
954	     * 平时只在「复尺提交时调中控（报价变更/自动下单）失败」的异步分支里被调用，正常流程很难复现。
955	     * 这里按 taskDispatchId 反射直接触发一次，并把解析出来的收件人/文案回显出来便于核验。
956	     * <p>
957	     * 注意：被调方法内部吞异常，所以返回 success 只代表「已触发」，实际是否收到 push 还要看客户端；
958	     * 回显里的 foremanId / designerId 为空则说明查不到收件人。
959	     *
960	     * @param taskDispatchId 复尺任务id
961	     */
962	    @ApiOperation("【测试】复尺调中控失败发IM push")
963	    @GetMapping("/backdoor/measure/pushResizeCommitFail")
964	    public ResultDTO<Map<String, Object>> pushResizeCommitFail(@RequestParam("taskDispatchId") Long taskDispatchId) {
965	        Preconditions.checkArgument(Objects.nonNull(taskDispatchId), "taskDispatchId 不能为空");
966	        Object measureService = ApplicationContextUtil.getApplicationContext().getBean(MaterialMeasureService.class);
967	        // 有可能是 CGLIB / JDK 动态代理，先拿到真正的目标对象再反射调用私有方法
968	        Object target = AopProxyUtils.getSingletonTarget(measureService);
969	        if (Objects.isNull(target)) {
970	            target = measureService;
971	        }
972	        try {
973	            Method method = AopUtils.getTargetClass(target)
974	                    .getDeclaredMethod("pushResizeCommitFailMsg", Long.class, Throwable.class);
975	            method.setAccessible(true);
976	            method.invoke(target, taskDispatchId, new RuntimeException("【测试】模拟变更下单失败"));
977	        } catch (InvocationTargetException e) {
978	            // 该方法约定自身不抛异常，真抛出来说明代码有问题
979	            logger.error("【测试】pushResizeCommitFailMsg 反射调用异常, taskDispatchId:{}", taskDispatchId, e.getTargetException());
980	            return new ResultDTO<>().fail("执行异常：" + e.getTargetException());
981	        } catch (Exception e) {
982	            logger.error("【测试】pushResizeCommitFailMsg 调用失败, taskDispatchId:{}", taskDispatchId, e);
983	            return new ResultDTO<>().fail("调用失败：" + e.getMessage());
984	        }
985	
986	        // 回显解析结果，便于核验「谁应该收到消息」
987	        Map<String, Object> result = new LinkedHashMap<>();
988	        result.put("taskDispatchId", taskDispatchId);
989	        TaskDispatch taskDispatch = taskDispatchDao.getById(taskDispatchId);
990	        if (Objects.isNull(taskDispatch)) {
991	            result.put("tip", "任务不存在，未发送任何消息");
992	            return new ResultDTO<>().success(result);
993	        }
994	        result.put("projectOrderId", taskDispatch.getProjectOrderId());
995	        result.put("materialName", taskDispatch.getMaterialName());
996	        result.put("taskType", taskDispatch.getTaskType());
997	        result.put("isRecheckScale", Objects.equals(taskDispatch.getTaskType(), TaskTypeEnum.RECHECK_SCALE.getValue()));
998	        result.put("channel", PushChannelEnum.RENWUTIXING.getCode());
999	        // 文案直接反射取实现里的方法，避免后门和线上文案两处维护
1000	        result.put("title", invokeMeasurePrivate(target, "buildResizeCommitFailTitle",
1001	                new Class<?>[] {TaskDispatch.class}, taskDispatch));
1002	
1003	        ProjectOrderDetailBO projectOrder = projectOrderManager.getProjectOrder(taskDispatch.getProjectOrderId());
1004	        if (Objects.isNull(projectOrder)) {
1005	            result.put("tip", "项目订单查不到：方法内部会 NPE 并被吞掉，实际不会发出任何消息");
1006	            return new ResultDTO<>().success(result);
1007	        }
1008	        result.put("foremanId", projectOrder.getForemanId());
1009	        result.put("designerId", projectOrder.getDesignerId());
1010	        result.put("content", invokeMeasurePrivate(target, "buildResizeCommitFailContent",
1011	                new Class<?>[] {ProjectOrderDetailBO.class, List.class}, projectOrder,
1012	                Lists.newArrayList("【测试】模拟变更返回的失败原因")));
1013	        // 跳转链接：PRD 要求「点击跳转至对应复尺任务的完成态快照」
1014	        Object startNode = invokeMeasurePrivate(target, "queryLatestStartNode", new Class<?>[] {Long.class},
1015	                taskDispatchId);
1016	        if (Objects.nonNull(startNode) && startNode instanceof TaskDispatchNode) {
1017	            result.put("url", invokeMeasurePrivate(target, "buildMeasureDetailUrl",
1018	                    new Class<?>[] {TaskDispatch.class, TaskDispatchNode.class}, taskDispatch, startNode));
1019	        } else {
1020	            result.put("url", null);
1021	            result.put("urlTip", "该复尺任务没有有效的 START 节点，线上跳转会是空");
1022	        }
1023	        result.put("tip", "已触发；foremanId / designerId 有值则对应角色应收到「任务提醒」push");
1024	        return new ResultDTO<>().success(result);
1025	    }
