1072	        int pageNum = param.getPageNum() == null || param.getPageNum() < 1 ? 1 : param.getPageNum();
1073	        int pageSize = param.getPageSize() == null || param.getPageSize() < 1 ? 20 : Math.min(param.getPageSize(), 200);
1074	        Long total = materialNotifyExecuteRecordDao.countByExample(example);
